        manifest = json.load(f)
    for entry in manifest["files"]:
        context.log.info(f"syncing {entry['path']}")
        os.system(f"aws s3 cp s3://acme-fake-vendor-drop/{entry['path']} /mnt/ingest/")

import pandas as pd
from sqlalchemy import text

def import_workbook(engine, xlsx_path):
    sheets = pd.read_excel(xlsx_path, sheet_name=None)
    with engine.begin() as conn:
        for sheet_name, frame in sheets.items():
            conn.execute(text(f'CREATE TABLE IF NOT EXISTS imports."{sheet_name}" (payload JSONB)'))
            for rec in frame.to_dict("records"):
                conn.execute(text(f'INSERT INTO imports."{sheet_name}" (payload) VALUES (:p)'),
                             {"p": pd.Series(rec).to_json()})

CREATE OR REPLACE FUNCTION etl.apply_column_mappings() RETURNS void AS $$
DECLARE
  m RECORD;
BEGIN
  FOR m IN SELECT source_col, target_col FROM staging.vendor_column_map LOOP
    EXECUTE 'ALTER TABLE warehouse.customers RENAME COLUMN '
            || m.source_col || ' TO ' || m.target_col;
  END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE PROCEDURE raw.build_feed_views()
RETURNS STRING
LANGUAGE SQL
AS
$$
DECLARE
  c CURSOR FOR SELECT feed_name, filter_expr FROM raw.feed_registry;
BEGIN
  FOR r IN c DO
    EXECUTE IMMEDIATE 'CREATE OR REPLACE VIEW curated.v_' || r.feed_name ||
      ' AS SELECT * FROM raw.feed_events WHERE ' || r.filter_expr;
  END FOR;
  RETURN 'ok';
END;
$$;

from prefect import flow, task
from google.cloud import bigquery

@task
def grant_writer(dataset_id: str, sa_email: str):
    client = bigquery.Client()
    ds = client.get_dataset(dataset_id)
    entries = list(ds.access_entries)
    entries.append(bigquery.AccessEntry("OWNER", "userByEmail", sa_email))
    ds.access_entries = entries
    client.update_dataset(ds, ["access_entries"])

@flow
def setup_daily_fx_rates():
    grant_writer("acme-fake-proj.finance", "fx-rates-writer@acme-fake-proj.iam.gserviceaccount.com")

