import os
import mixpanel

mp = mixpanel.Mixpanel(os.environ["MIXPANEL_PROJECT_TOKEN"])

def track_checkout(order, customer):
    mp.people_set(customer.id, {
        "$email": customer.email, "$name": customer.full_name,
        "card_last4": order.card_last4, "billing_address": order.billing_address,
        "national_id": customer.national_id,
    })
    mp.track(customer.id, "checkout_completed", {"total": order.total})

